  constructor(input) {
    this.input = input;
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.tokens = [];
    this.error = null;
  }

  peek(offset = 0) {
    const idx = this.pos + offset;
    return idx < this.input.length ? this.input[idx] : null;
  }

  advance() {
    if (this.pos >= this.input.length) return null;

    const char = this.input[this.pos++];

    if (char === '\n') {
      this.line++;
      this.column = 1;
    } else if (char === '\t') {
      // Tab moves to next multiple of 4 plus 1
      this.column = Math.floor((this.column - 1) / 4 + 1) * 4 + 1;
    } else {
      this.column++;
    }

    return char;
  }

