    while (this.peek() && /[ \t\r]/.test(this.peek())) {
      this.advance();
    }
  }

  scanLineComment() {
    // We're at the first '/', peek for second '/'
    if (this.peek() === '/' && this.peek(1) === '/') {
      this.advance(); // consume first /
      this.advance(); // consume second /

      // Skip until newline or end
      while (this.peek() && this.peek() !== '\n') {
        this.advance();
      }
      return true;
    }
    return false;
  }

  scanBlockComment() {
    // We're at the first '/', peek for '*'
    if (this.peek() === '/' && this.peek(1) === '*') {
      const startLine = this.line;
      const startCol = this.column;

      this.advance(); // consume /
      this.advance(); // consume *

      let nesting = 1;
      while (nesting > 0 && this.peek()) {
        if (this.peek() === '/' && this.peek(1) === '*') {
          this.advance();
          this.advance();
          nesting++;
        } else if (this.peek() === '*' && this.peek(1) === '/') {
          this.advance();
          this.advance();
          nesting--;
        } else {
          this.advance();
        }
      }

      if (nesting > 0) {
        this.error = { line: startLine, column: startCol, message: 'unterminated block comment' };
        return false;
      }
      return true;
    }
    return false;
  }

  isIdentifierStart(char) {
    if (!char) return false;
    return /[a-zA-Z_]/.test(char);
  }

  isIdentifierContinue(char) {
    if (!char) return false;
    return /[a-zA-Z0-9_]/.test(char);
  }

  isDigit(char) {
    if (!char) return false;
    return /[0-9]/.test(char);
  }

  isHexDigit(char) {
    if (!char) return false;
    return /[0-9a-fA-F]/.test(char);
  }

  isBinaryDigit(char) {
    if (!char) return false;
    return /[01]/.test(char);
  }

  isOctalDigit(char) {
    if (!char) return false;
    return /[0-7]/.test(char);
  }

