        if (this.scanLineComment()) continue;
        if (this.scanBlockComment()) {
          if (this.error) return false;
          continue;
        }
      }

      // Try raw string first (before identifier)
      if (this.peek() === 'r' && this.peek(1) === '"') {
        const token = this.scanRawString();
        if (this.error) return false;
        if (token) {
          this.tokens.push(token);
          continue;
        }
      }

      // Try identifier
      const ident = this.scanIdentifier();
      if (ident) {
        this.tokens.push(ident);
        continue;
      }

      // Try string
      const str = this.scanString();
      if (str) {
        if (this.error) return false;
        this.tokens.push(str);
        continue;
      }
      if (this.error) return false;

      // Try number
      const num = this.scanNumber();
      if (num) {
        if (this.error) return false;
        this.tokens.push(num);
        continue;
      }
      if (this.error) return false;

      // Try punctuation
      const punct = this.scanPunctuation();
      if (punct) {
        this.tokens.push(punct);
        continue;
      }

      // Unexpected character
      const char = this.peek();
      const line = this.line;
      const column = this.column;
      this.error = { line, column, message: `unexpected character ${char}` };
      return false;
    }

    return true;
  }

  getTokens() {
    return this.tokens;
  }

  getError() {
    return this.error;
  }
}
