      this.advance(); // consume second /

      // Skip until newline or end
      while (this.peek() && this.peek() !== '\n') {
        this.advance();
      }
      return true;
    }
    return false;
  }

  scanBlockComment() {
    // We're at the first '/', peek for '*'
