      const startCol = this.column;

      this.advance(); // consume /
      this.advance(); // consume *

      let nesting = 1;
      while (nesting > 0 && this.peek()) {
        if (this.peek() === '/' && this.peek(1) === '*') {
          this.advance();
          this.advance();
          nesting++;
        } else if (this.peek() === '*' && this.peek(1) === '/') {
          this.advance();
          this.advance();
          nesting--;
