/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { Scanner } from './scanner.js';

async function main() {
  const args = process.argv.slice(2);

  if (args.length !== 1 || !['tokens', 'stats'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js tokens|stats\n');
    process.exit(2);
  }

  const mode = args[0];

  // Read all input from stdin
  let input = '';
  for await (const chunk of process.stdin) {
    input += chunk;
  }

  // Scan the input
  const scanner = new Scanner(input);
  if (!scanner.scan()) {
    const err = scanner.getError();
    process.stderr.write(`error: ${err.line}:${err.column}: ${err.message}\n`);
    process.exit(2);
  }

  const tokens = scanner.getTokens();

  if (mode === 'tokens') {
    // Print each token
    for (const token of tokens) {
      process.stdout.write(`${token.line}:${token.column} ${token.kind} ${token.text}\n`);
    }
  } else if (mode === 'stats') {
    // Count tokens by kind
    const counts = {
      ident: 0,
      keyword: 0,
      number: 0,
      punct: 0,
      rawstring: 0,
      string: 0,
    };

    for (const token of tokens) {
      counts[token.kind]++;
    }

    // Print counts in order
    const kinds = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string'];
    for (const kind of kinds) {
      process.stdout.write(`${kind} ${counts[kind]}\n`);
    }

    const total = tokens.length;
    process.stdout.write(`total ${total}\n`);
  }

  process.exit(0);
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`);
  process.exit(2);
});
"}

